script:
frappe.ui.form.on('Supplier', {
    supplier_name: function(frm) {
        if (frm.doc.supplier_name) {
            // Get first character and convert to uppercase
            let initial = frm.doc.supplier_name.charAt(0).toUpperCase();

            // Set value to custom field
            frm.set_value('custom_initial', initial);
        } else {
            // Clear if empty
            frm.set_value('custom_initial', '');
        }
    }
});

frappe.ui.form.on('Customer', {
    customer_name: function(frm) {
        if (frm.doc.customer_name) {
            // Get first character and convert to uppercase
            let initial = frm.doc.customer_name.charAt(0).toUpperCase();

            // Set value to custom field
            frm.set_value('custom_cn_initial', initial);
        } else {
            // Clear if empty
            frm.set_value('custom_cn_initial', '');
        }
    }
});

frappe.ui.form.on('Item', {
    validate: function(frm) {
        let value = frm.doc.item_code || "";

        if (value.length !== 10) {
            frappe.throw("Item Code must be exactly 10 characters");
        }
    }
});

frappe.ui.form.on('User', {
    refresh: function(frm) {
        setTimeout(function() {
            hide_roles();
            filter_modules();
            hide_bulk_buttons();
        }, 700);
    }
});

function hide_roles() {
    const blacklist = ['System Manager', 'Script Manager'];

    blacklist.forEach(function(role) {
        $(`[data-fieldname="roles_html"] input[data-unit="${role}"]`)
            .closest('div.unit-checkbox')
            .hide();
    });
}

function filter_modules() {
    const whitelist = [
        'Accounts',
        'Buying',
        'Selling',
        'Stock',
        'Core'
    ];

    $('[data-fieldname="modules_html"] div.unit-checkbox').each(function() {
        const unit = $(this).find('input').data('unit');
        if (!whitelist.includes(unit)) {
            $(this).hide();
        }
    });
}

function hide_bulk_buttons() {
    $('div.bulk-select-options').hide();
}

// Immediate alert when user manually changes rate on an item row
frappe.ui.form.on('Sales Invoice Item', {
	rate(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (!row.item_code || !row.warehouse || row.is_free_item) return;

		frappe.call({
			method: 'frappe.client.get_value',
			args: {
				doctype: 'Bin',
				filters: { item_code: row.item_code, warehouse: row.warehouse },
				fieldname: 'valuation_rate'
			},
			callback(r) {
				if (!r.message) return;
				const val_rate = flt(r.message.valuation_rate);
				if (val_rate > 0 && flt(row.rate) < val_rate) {
					frappe.show_alert({
						message: __('Row {0} ({1}): Rate {2} is below valuation rate {3}', [
							row.idx,
							row.item_name,
							format_currency(row.rate, frm.doc.currency),
							format_currency(val_rate, frm.doc.currency)
						]),
						indicator: 'orange'
					}, 8);
				}
			}
		});
	}
});

// Collect below-cost warnings during validate, display them after save
// (showing during validate causes Frappe's post-save msgprint to clear the body)
frappe.ui.form.on('Sales Invoice', {
	validate(frm) {
		const warnings = [];
		(frm.doc.items || []).forEach(row => {
			const val_rate = flt(row.incoming_rate);
			if (!row.is_free_item && val_rate > 0 && flt(row.rate) < val_rate) {
				warnings.push(
					`<b>Row ${row.idx} — ${row.item_name}</b><br>` +
					`Selling rate: ${format_currency(row.rate, frm.doc.currency)} | ` +
					`Valuation rate: ${format_currency(val_rate, frm.doc.currency)}`
				);
			}
		});
		frm.__below_cost_warnings = warnings;
	},
	after_save(frm) {
		const warnings = frm.__below_cost_warnings;
		if (!warnings || !warnings.length) return;
		frm.__below_cost_warnings = null;
		frappe.msgprint({
			title: __('Selling Below Cost'),
			message:
				__('The following items are priced below their valuation rate. You may still save, but please verify this is intentional before proceeding.') +
				'<br><br>' +
				warnings.join('<br><br>'),
			indicator: 'orange'
		});
	}
});
